@media not (forced-colors) {
  --background-color-box-info: light-dark(var(--layout-background-1), var(--layout-background-2));
  --in-content-box-info-border: light-dark(var(--layout-border-0), transparent);
  --button-background-color: light-dark(var(--grey-90-a10), rgba(249, 249, 250, 0.1));
  --button-background-color-hover: light-dark(var(--grey-90-a20), rgba(249, 249, 250, 0.15));
  --button-background-color-active: light-dark(var(--grey-90-a30), rgba(249, 249, 250, 0.2));
  --in-content-categories-background: var(--layout-background-2);
  --in-content-categories-border: var(--in-content-categories-background);
  --color-accent-primary-selected-unfocused: light-dark(var(--color-gray-20), rgba(249, 249, 250, 0.05));
  --in-content-item-hover: color-mix(in srgb, currentColor 12%, transparent);
  --color-accent-primary-selected: color-mix(in srgb, currentColor 20%, transparent);
  --text-color-accent-primary-selected: var(--text-color);
  --button-background-color-primary: AccentColor;
  --button-background-color-primary-hover: color-mix(in srgb, AccentColor 80%, black);
  --button-background-color-primary-active: color-mix(in srgb, AccentColor 70%, black);
  --button-text-color-primary: AccentColorText;
  --in-content-focus-outline-color: AccentColor;
  --in-content-accent-color: AccentColor;
